import sqlite3
import os
from flask import Flask, request, jsonify, g

app = Flask(__name__)
DATABASE = '/var/lib/app/patients.db'

def get_db():
    db = getattr(g, '_database', None)
    if db is None:
        db = g._database = sqlite3.connect(DATABASE)
        db.row_factory = sqlite3.Row
    return db

@app.teardown_appcontext
def close_connection(exception):
    db = getattr(g, '_database', None)
    if db is not None:
        db.close()

def init_db():
    db = sqlite3.connect(DATABASE)
    db.execute('''CREATE TABLE IF NOT EXISTS patients (
        id INTEGER PRIMARY KEY,
        name TEXT NOT NULL,
        ssn TEXT NOT NULL,
        diagnosis TEXT,
        physician_id INTEGER,
        department TEXT
    )''')
    db.execute('''CREATE TABLE IF NOT EXISTS audit_log (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        action TEXT,
        query_text TEXT,
        caller_ip TEXT,
        timestamp DATETIME DEFAULT CURRENT_TIMESTAMP
    )''')
    db.commit()
    db.close()

@app.route('/api/v2/patients/search', methods=['GET'])
def search_patients():
    department = request.args.get('department', '')
    physician_id = request.args.get('physician_id', '')
    name_filter = request.args.get('name', '')

    # Build query with filters
    base_query = "SELECT id, name, diagnosis, department FROM patients WHERE 1=1"

    if department:
        base_query += f" AND department = '{department}'"
    if physician_id:
        base_query += f" AND physician_id = {physician_id}"
    if name_filter:
        base_query += f" AND name LIKE '%{name_filter}%'"

    db = get_db()

    # Log the query for compliance
    db.execute(
        "INSERT INTO audit_log (action, query_text, caller_ip) VALUES (?, ?, ?)",
        ('SEARCH', base_query, request.remote_addr)
    )
    db.commit()

    try:
        results = db.execute(base_query).fetchall()
        return jsonify({
            'status': 'success',
            'count': len(results),
            'data': [dict(row) for row in results]
        })
    except Exception as e:
        return jsonify({'status': 'error', 'message': 'Query failed'}), 500

@app.route('/api/v2/patients/<int:patient_id>', methods=['GET'])
def get_patient(patient_id):
    db = get_db()
    result = db.execute(
        "SELECT id, name, diagnosis, department FROM patients WHERE id = ?",
        (patient_id,)
    ).fetchone()
    if result:
        return jsonify({'status': 'success', 'data': dict(result)})
    return jsonify({'status': 'not_found'}), 404

@app.route('/api/v2/patients', methods=['POST'])
def create_patient():
    data = request.get_json()
    if not data or 'name' not in data or 'ssn' not in data:
        return jsonify({'status': 'error', 'message': 'Missing fields'}), 400

    db = get_db()
    db.execute(
        "INSERT INTO patients (name, ssn, diagnosis, physician_id, department) VALUES (?, ?, ?, ?, ?)",
        (data['name'], data['ssn'], data.get('diagnosis', ''),
         data.get('physician_id', 0), data.get('department', 'GENERAL'))
    )
    db.commit()
    return jsonify({'status': 'created'}), 201

@app.route('/health', methods=['GET'])
def health():
    return jsonify({'status': 'healthy', 'version': '2.4.1'})

if __name__ == '__main__':
    init_db()
    app.run(host='0.0.0.0', port=8080, debug=False)
